package com.sispro.obra.controller;
import com.sispro.obra.dao.*;
import com.sispro.obra.model.*;
import com.sispro.obra.service.*;
import java.io.IOException;
import java.time.LocalDate;
import java.util.*;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class ModulosController {
 private final ObraDAO obras;private final IncidenciaDAO incidencias;private final UsuarioDAO usuarios;private final EtapaDAO etapas;private final TareaDAO tareas;private final ComentarioDAO comentarios;private final AsignacionObraDAO asignaciones;private final AuditoriaDAO log;private final AccesoService acceso;private final AuditoriaService audit;
 public ModulosController(ObraDAO obras,IncidenciaDAO incidencias,UsuarioDAO usuarios,EtapaDAO etapas,TareaDAO tareas,ComentarioDAO comentarios,AsignacionObraDAO asignaciones,AuditoriaDAO log,AccesoService acceso,AuditoriaService audit){this.obras=obras;this.incidencias=incidencias;this.usuarios=usuarios;this.etapas=etapas;this.tareas=tareas;this.comentarios=comentarios;this.asignaciones=asignaciones;this.log=log;this.acceso=acceso;this.audit=audit;}
 private String bloqueoObra(Obra o,String destino,RedirectAttributes r){if(o.estado==EstadoObra.CERRADA){r.addFlashAttribute("error","La obra está cerrada: solo se permite consulta.");return "redirect:"+destino;}return null;}
 @ModelAttribute("sesionUsuario") Usuario sesion(Authentication a){return a==null?null:acceso.actual(a);}
 @GetMapping("/obras/{id}") String detalle(@PathVariable Long id,Authentication a,Model m){Obra o=obras.findById(id).orElseThrow();acceso.exigirVer(acceso.actual(a),o);m.addAttribute("obra",o);m.addAttribute("etapas",etapas.findByObraIdOrderByInicioAsc(id));m.addAttribute("tareas",tareas.findByObraIdOrderByInicioAsc(id));m.addAttribute("incidencias",incidencias.findByObraIdOrderByCreadaDesc(id));m.addAttribute("asignaciones",asignaciones.findByObraId(id));Usuario yo=acceso.actual(a);boolean gestion=acceso.esAdmin(yo)||acceso.esSupervisor(yo);m.addAttribute("usuarios",gestion?usuarios.findAll():List.<Usuario>of());m.addAttribute("integrantes",gestion?usuarios.findAll().stream().filter(x->acceso.puedeVer(x,o)).toList():List.<Usuario>of());return "obra-detalle";}
 @PostMapping("/obras/{id}/asignar") String asignar(@PathVariable Long id,@RequestParam Long usuarioId,Authentication a,RedirectAttributes r){Obra o=obras.findById(id).orElseThrow();acceso.exigirGestion(acceso.actual(a),o);{String b=bloqueoObra(o,"/obras/"+id,r);if(b!=null)return b;}Usuario u=usuarios.findById(usuarioId).orElseThrow();if(!asignaciones.existsByObraIdAndUsuarioId(id,usuarioId)){AsignacionObra x=new AsignacionObra();x.obra=o;x.usuario=u;asignaciones.save(x);audit.registrar(a.getName(),"ASIGNAR_USUARIO","Obra "+id+" / "+u.correo);}r.addFlashAttribute("ok","Integrante asignado.");return "redirect:/obras/"+id;}
 @PostMapping("/obras/{id}/etapas/nueva") String etapa(@PathVariable Long id,@RequestParam String nombre,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate inicio,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate fin,Authentication a,RedirectAttributes r){Obra o=obras.findById(id).orElseThrow();acceso.exigirGestion(acceso.actual(a),o);{String b=bloqueoObra(o,"/obras/"+id,r);if(b!=null)return b;}if(nombre.isBlank()||fin.isBefore(inicio)){r.addFlashAttribute("error","Nombre o fechas inválidas.");}else{Etapa e=new Etapa();e.obra=o;e.nombre=nombre;e.inicio=inicio;e.fin=fin;etapas.save(e);audit.registrar(a.getName(),"CREAR_ETAPA",nombre);r.addFlashAttribute("ok","Etapa registrada.");}return "redirect:/obras/"+id;}
 @PostMapping("/obras/{id}/tareas/nueva") String tarea(@PathVariable Long id,@RequestParam String nombre,@RequestParam String descripcion,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate inicio,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate fin,@RequestParam(required=false) Long etapaId,@RequestParam(required=false) Long responsableId,Authentication a,RedirectAttributes r){Obra o=obras.findById(id).orElseThrow();acceso.exigirGestion(acceso.actual(a),o);{String b=bloqueoObra(o,"/obras/"+id,r);if(b!=null)return b;}if(nombre.isBlank()||fin.isBefore(inicio)){r.addFlashAttribute("error","Nombre o fechas inválidas.");return "redirect:/obras/"+id;}Tarea t=new Tarea();t.obra=o;t.nombre=nombre;t.descripcion=descripcion;t.inicio=inicio;t.fin=fin;if(etapaId!=null){t.etapa=etapas.findById(etapaId).orElseThrow();if(!t.etapa.obra.id.equals(id)){r.addFlashAttribute("error","La etapa elegida no pertenece a la obra.");return "redirect:/obras/"+id;}}if(responsableId!=null){t.responsable=usuarios.findById(responsableId).orElseThrow();if(!acceso.puedeVer(t.responsable,o)){r.addFlashAttribute("error","El responsable elegido no pertenece a la obra.");return "redirect:/obras/"+id;}}tareas.save(t);audit.registrar(a.getName(),"CREAR_TAREA",nombre);r.addFlashAttribute("ok","Tarea creada.");return "redirect:/obras/"+id;}
 @PostMapping("/tareas/{id}/avance") String avance(@PathVariable Long id,@RequestParam Integer porcentaje,@RequestParam(required=false) String justificacion,Authentication a,RedirectAttributes r){Tarea t=tareas.findById(id).orElseThrow();Usuario u=acceso.actual(a);acceso.exigirVer(u,t.obra);{String b=bloqueoObra(t.obra,"/obras/"+t.obra.id,r);if(b!=null)return b;}if(!(acceso.esAdmin(u)||acceso.esSupervisor(u)&&acceso.puedeVer(u,t.obra)||t.responsable!=null&&t.responsable.id.equals(u.id)))throw new org.springframework.security.access.AccessDeniedException("Sin permiso");if(porcentaje<0||porcentaje>100){r.addFlashAttribute("error","Avance de 0 a 100.");}else if(porcentaje<t.avance&&(justificacion==null||justificacion.isBlank())){r.addFlashAttribute("error","Justifique el retroceso del avance.");}else{t.avance=porcentaje;tareas.save(t);audit.registrar(a.getName(),"ACTUALIZAR_AVANCE","Tarea "+id+": "+porcentaje+"% "+(justificacion==null?"":justificacion));r.addFlashAttribute("ok","Avance actualizado.");}return "redirect:/obras/"+t.obra.id;}
 @GetMapping("/incidencias/{id}") String incidencia(@PathVariable Long id,Authentication a,Model m){Incidencia i=incidencias.findById(id).orElseThrow();acceso.exigirVer(acceso.actual(a),i.obra);m.addAttribute("incidencia",i);m.addAttribute("comentarios",comentarios.findByIncidenciaIdOrderByCreadaAsc(id));m.addAttribute("integrantes",usuarios.findAll().stream().filter(u->acceso.puedeVer(u,i.obra)).toList());m.addAttribute("prioridades",Prioridad.values());return "incidencia-detalle";}
 @PostMapping("/incidencias/{id}/comentarios") String comentar(@PathVariable Long id,@RequestParam String texto,Authentication a,RedirectAttributes r){Incidencia i=incidencias.findById(id).orElseThrow();Usuario u=acceso.actual(a);acceso.exigirVer(u,i.obra);{String b=bloqueoObra(i.obra,"/incidencias/"+id,r);if(b!=null)return b;}if(texto==null||texto.isBlank())r.addFlashAttribute("error","El comentario no puede estar vacío.");else{Comentario c=new Comentario();c.autor=u;c.incidencia=i;c.texto=texto.trim();comentarios.save(c);audit.registrar(a.getName(),"COMENTAR","Incidencia "+id);r.addFlashAttribute("ok","Comentario publicado.");}return "redirect:/incidencias/"+id;}
 @PostMapping("/incidencias/{id}/asignar") String asignarIncidencia(@PathVariable Long id,@RequestParam Long usuarioId,@RequestParam Prioridad prioridad,Authentication a,RedirectAttributes r){Incidencia i=incidencias.findById(id).orElseThrow();acceso.exigirGestion(acceso.actual(a),i.obra);{String b=bloqueoObra(i.obra,"/incidencias/"+id,r);if(b!=null)return b;}if(i.estado==EstadoIncidencia.RESUELTA||i.estado==EstadoIncidencia.ANULADA){r.addFlashAttribute("error","No se puede reasignar una incidencia resuelta o anulada.");return "redirect:/incidencias/"+id;}Usuario u=usuarios.findById(usuarioId).orElseThrow();if(!acceso.puedeVer(u,i.obra)){r.addFlashAttribute("error","El responsable elegido no pertenece a la obra.");return "redirect:/incidencias/"+id;}java.time.LocalDateTime ahora=java.time.LocalDateTime.now();i.responsable=u;i.prioridad=prioridad;i.actualizada=ahora;if(i.estado==EstadoIncidencia.PENDIENTE)i.estado=EstadoIncidencia.ASIGNADA;if(i.fechaAsignacion==null)i.fechaAsignacion=ahora;incidencias.save(i);audit.registrar(a.getName(),"ASIGNAR_INCIDENCIA","Incidencia "+id);r.addFlashAttribute("ok","Incidencia asignada.");return "redirect:/incidencias/"+id;}
 @PostMapping("/incidencias/{id}/anular") String anular(@PathVariable Long id,@RequestParam String motivo,Authentication a,RedirectAttributes r){Incidencia i=incidencias.findById(id).orElseThrow();acceso.exigirGestion(acceso.actual(a),i.obra);{String b=bloqueoObra(i.obra,"/incidencias/"+id,r);if(b!=null)return b;}if(i.estado==EstadoIncidencia.RESUELTA||i.estado==EstadoIncidencia.ANULADA||motivo.isBlank()){r.addFlashAttribute("error","Indica motivo; solo se anulan incidencias abiertas.");}else{i.estado=EstadoIncidencia.ANULADA;i.actualizada=java.time.LocalDateTime.now();i.motivoAnulacion=motivo;incidencias.save(i);audit.registrar(a.getName(),"ANULAR_INCIDENCIA","Incidencia "+id);r.addFlashAttribute("ok","Incidencia anulada.");}return "redirect:/incidencias/"+id;}
 @GetMapping("/cronograma") String cronograma(Authentication a,Model m){Usuario u=acceso.actual(a);m.addAttribute("tareas",tareas.findAll().stream().filter(t->acceso.puedeVer(u,t.obra)).toList());return "cronograma";}
 @GetMapping("/reportes") String reportes(Authentication a,Model m){Usuario u=acceso.actual(a);List<Obra> lista=acceso.visibles(u);List<Incidencia> inc=incidencias.findAll().stream().filter(i->acceso.puedeVer(u,i.obra)).toList();m.addAttribute("obras",lista);m.addAttribute("incidencias",inc);java.util.Map<String,Long> semanas=new java.util.TreeMap<>();for(Incidencia x:inc)if(x.creada!=null){java.time.LocalDate d=x.creada.toLocalDate();semanas.merge(String.format("%d-S%02d",d.get(java.time.temporal.IsoFields.WEEK_BASED_YEAR),d.get(java.time.temporal.IsoFields.WEEK_OF_WEEK_BASED_YEAR)),1L,Long::sum);}m.addAttribute("porSemana",semanas);m.addAttribute("tiempoRespuesta",promedio(inc,x->x.fechaAsignacion));m.addAttribute("tiempoResolucion",promedio(inc,x->x.fechaResolucion));m.addAttribute("pendientes",inc.stream().filter(i->i.estado!=EstadoIncidencia.RESUELTA&&i.estado!=EstadoIncidencia.ANULADA).count());m.addAttribute("resueltas",inc.stream().filter(i->i.estado==EstadoIncidencia.RESUELTA).count());return "reportes";}
 @GetMapping(value="/reportes/incidencias.csv",produces="text/csv") ResponseEntity<byte[]> csv(Authentication a){Usuario u=acceso.actual(a);StringBuilder sb=new StringBuilder("ID;Obra;Titulo;Tipo;Estado;Prioridad\n");for(Incidencia i:incidencias.findAll())if(acceso.puedeVer(u,i.obra))sb.append(i.id).append(';').append(csvCell(i.obra.nombre)).append(';').append(csvCell(i.titulo)).append(';').append(i.tipo).append(';').append(i.estado).append(';').append(i.prioridad).append('\n');byte[] bytes=("\uFEFF"+sb).getBytes(java.nio.charset.StandardCharsets.UTF_8);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=incidencias.csv").body(bytes);}
 private static String promedio(List<Incidencia> inc,java.util.function.Function<Incidencia,java.time.LocalDateTime> fin){var media=inc.stream().filter(x->x.creada!=null&&fin.apply(x)!=null).mapToLong(x->java.time.Duration.between(x.creada,fin.apply(x)).toMinutes()).average();return media.isPresent()?String.format("%.1f h",media.getAsDouble()/60):"Sin datos";}
 private String csvCell(String x){String s=x==null?"":x;if(!s.isEmpty()&&"=+-@\t\r".indexOf(s.charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"").replace("\r"," ").replace("\n"," ")+"\"";}
 @GetMapping("/auditoria") String auditoria(Authentication a,Model m){m.addAttribute("logs",log.findTop100ByOrderByFechaDesc());return "auditoria";}
}
